#!/usr/bin/env bash
# Deploy dsh-web-tray to WSL and the Windows user profile.
#
# Usage:
#   ./install.sh                    # deploy; write config if it is missing
#   ./install.sh --restart          # deploy and restart the tray
#   ./install.sh --refresh-config   # re-detect the environment and rewrite config
#
# The generated file windows-appdir/dsh-web-tray.config.ps1 is the single
# source of truth for the WSL distro/user/endpoint. It is not tracked in git.
#
# Detection overrides:
#   DSH_WSL_DISTRO   distro name              (default: $WSL_DISTRO_NAME)
#   DSH_WSL_USER     WSL user                 (default: current user)
#   DSH_WEB_PORT     dsh web port             (default: detected, else 3080)
#   DSH_WIN_APPDIR   Windows app dir in WSL form
#                    (default: %LOCALAPPDATA%\DSH resolved via PowerShell)
set -euo pipefail

ROOT="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"

RESTART=0
REFRESH_CONFIG=0
for arg in "$@"; do
  case "$arg" in
    --restart)        RESTART=1 ;;
    --refresh-config) REFRESH_CONFIG=1 ;;
    -h|--help)
      cat <<'EOF'
Usage: ./install.sh [--restart] [--refresh-config]

  --restart         restart the tray after deploying
  --refresh-config  re-detect distro/user/port and rewrite the config file
                    (default: keep an existing config untouched)
EOF
      exit 0
      ;;
    *)
      echo "unknown option: $arg" >&2
      exit 2
      ;;
  esac
done

PS_EXE="$(command -v powershell.exe || true)"
if [[ -z "$PS_EXE" && -x "/mnt/c/Windows/System32/WindowsPowerShell/v1.0/powershell.exe" ]]; then
  PS_EXE="/mnt/c/Windows/System32/WindowsPowerShell/v1.0/powershell.exe"
fi
if [[ -z "$PS_EXE" ]]; then
  echo "powershell.exe not found; WSL interop is required." >&2
  exit 1
fi

if [[ -z "${DSH_WIN_APPDIR:-}" ]] && command -v wslpath >/dev/null 2>&1; then
  win_local="$("$PS_EXE" -NoProfile -Command '$env:LOCALAPPDATA' | tr -d '\r')"
  if [[ -n "$win_local" ]]; then
    DSH_WIN_APPDIR="$(wslpath -u "$win_local")/DSH"
  fi
fi
if [[ -z "${DSH_WIN_APPDIR:-}" ]]; then
  echo "cannot resolve %LOCALAPPDATA%; set DSH_WIN_APPDIR" >&2
  exit 1
fi

detect_distro() {
  if [[ -n "${DSH_WSL_DISTRO:-}" ]]; then
    printf '%s\n' "$DSH_WSL_DISTRO"
    return
  fi
  if [[ -n "${WSL_DISTRO_NAME:-}" ]]; then
    printf '%s\n' "$WSL_DISTRO_NAME"
    return
  fi
  local d
  d="$(wsl.exe -l -q 2>/dev/null \
    | tr -d '\0\r' \
    | sed 's/^\xFF\xFE//' \
    | sed '/^[[:space:]]*$/d' \
    | head -1 || true)"
  printf '%s\n' "${d:-Ubuntu}"
}

detect_user() {
  if [[ -n "${DSH_WSL_USER:-}" ]]; then
    printf '%s\n' "$DSH_WSL_USER"
    return
  fi
  if [[ "${EUID}" -eq 0 ]]; then
    local u
    u="$(sed -n 's/^[[:space:]]*default[[:space:]]*=[[:space:]]*//p' /etc/wsl.conf 2>/dev/null | head -1)"
    if [[ -n "$u" ]]; then
      printf '%s\n' "$u"
      return
    fi
    echo "running as root; set DSH_WSL_USER to the WSL user that runs dsh" >&2
    return 1
  fi
  id -un
}

home_of() {
  local u="$1" h=""
  if [[ "$u" == "$(id -un)" ]]; then
    printf '%s\n' "$HOME"
    return
  fi
  h="$(getent passwd "$u" 2>/dev/null | cut -d: -f6 || true)"
  printf '%s\n' "${h:-/home/$u}"
}

detect_port() {
  if [[ -n "${DSH_WEB_PORT:-}" ]]; then
    printf '%s\n' "$DSH_WEB_PORT"
    return
  fi
  local port pid
  while read -r port pid; do
    [[ -n "$port" && -n "$pid" ]] || continue
    if tr '\0' ' ' < "/proc/$pid/cmdline" 2>/dev/null \
      | grep -qE '(bin\.js|/dsh)( |.* )web( |$)'; then
      printf '%s\n' "$port"
      return
    fi
  done < <(ss -ltnp 2>/dev/null \
    | sed -n 's/.*:\([0-9][0-9]*\)[[:space:]].*pid=\([0-9][0-9]*\).*/\1 \2/p')
  printf '3080\n'
}

ps_quote() {
  local v="$1"
  v="${v//\'/\'\'}"
  printf "'%s'" "$v"
}

write_config() {
  local distro="$1" user="$2" script="$3" log="$4" host="$5" port="$6"
  local f="$DSH_WIN_APPDIR/dsh-web-tray.config.ps1"
  local tmp="$f.tmp"
  {
    printf '# Generated by install.sh on %s\n' "$(date -Is)"
    printf '# Describes this machine; not tracked in git.\n'
    printf '# Re-run ./install.sh --refresh-config to regenerate.\n'
    printf '\n'
    printf '$script:Distro    = %s\n' "$(ps_quote "$distro")"
    printf '$script:WslUser   = %s\n' "$(ps_quote "$user")"
    printf '$script:WslScript = %s\n' "$(ps_quote "$script")"
    printf '$script:WslLog    = %s\n' "$(ps_quote "$log")"
    printf '$script:WebHost   = %s\n' "$(ps_quote "$host")"
    printf '$script:WebPort   = %s\n' "$(ps_quote "$port")"
  } > "$tmp"
  # PowerShell 5.1 needs a BOM to decode the comments as UTF-8.
  printf '\xEF\xBB\xBF' > "$f"
  cat "$tmp" >> "$f"
  rm -f "$tmp"
}

DISTRO="$(detect_distro)"
WSL_USER="$(detect_user)"
USER_HOME="$(home_of "$WSL_USER")"
WSL_BIN_DIR="$USER_HOME/.local/bin"
WSL_SCRIPT="$WSL_BIN_DIR/dsh-web"

# The tray launches dsh-web through wsl.exe, which does not inherit the
# interactive shell's XDG_STATE_HOME, so keep the default state dir here.
WSL_LOG="$USER_HOME/.local/state/dsh-web/web.log"

WEB_HOST='127.0.0.1'
WEB_PORT="$(detect_port)"
CONFIG="$DSH_WIN_APPDIR/dsh-web-tray.config.ps1"

echo "repo:       $ROOT"
echo "distro:     $DISTRO"
echo "user:       $WSL_USER ($USER_HOME)"
echo "port:       $WEB_PORT"
echo "WSL:        $WSL_SCRIPT"
echo "Windows:    $DSH_WIN_APPDIR"
echo "PowerShell: $PS_EXE"

mkdir -p "$WSL_BIN_DIR" "$DSH_WIN_APPDIR"

if [[ -f "$CONFIG" && "$REFRESH_CONFIG" -ne 1 ]]; then
  echo "config:     $CONFIG (kept; --refresh-config to re-detect)"
else
  write_config "$DISTRO" "$WSL_USER" "$WSL_SCRIPT" "$WSL_LOG" "$WEB_HOST" "$WEB_PORT"
  echo "config:     $CONFIG (generated)"
fi

install -m 755 "$ROOT/bin/dsh-web" "$WSL_BIN_DIR/dsh-web"

cp "$ROOT/windows/dsh-web-tray.ps1" "$DSH_WIN_APPDIR/"
cp "$ROOT/windows/dsh-web-tray.vbs" "$DSH_WIN_APPDIR/"
cp "$ROOT/windows/dsh-web-autostart.vbs" "$DSH_WIN_APPDIR/"
cp "$ROOT/windows/install.ps1" "$DSH_WIN_APPDIR/"
cp "$ROOT/windows/README.txt" "$DSH_WIN_APPDIR/"
cp "$ROOT/windows/icons/"*.ico "$DSH_WIN_APPDIR/"

win_app_win="$(wslpath -w "$DSH_WIN_APPDIR")"
ps_args=()
if [[ "$RESTART" -eq 1 ]]; then
  ps_args+=("-Restart")
fi
"$PS_EXE" -NoProfile -ExecutionPolicy Bypass -File "${win_app_win}\\install.ps1" "${ps_args[@]}"

echo
echo "Done. Shortcuts: desktop and Start Menu -> DSH Web Tray"
echo "If the tray is not running, launch it from the desktop shortcut."
